/* 第一屏容器：固定高度 = 屏设计高（矩形 429，胶囊/圆形在 @media 覆盖），flex column 居中，flex-shrink:0 不被纵向滚动压缩 */
.screen1 { width: 100%; height: 429px; flex-direction: column; align-items: center; flex-shrink: 0; }

/* 状态栏：高度由 JS 动态计算（design 高 + 安全偏移），时间靠左 */

// 屏幕形态/安全偏移：状态栏高度 = 设计高 + 物理安全偏移换算的设计 px；
// 分类行顶部固定在 designTop（设计 top 值），故其 margin-top 动态补偿
adjustForScreen() {
  var self = this
  device.getInfo({
    success: function(data) {
      var screenWidth = data.screenWidth
      var shape = data.screenShape
      var safeTopPx = 0
      var base = 17
      var designTop = 60
      var iconW = 58
      var spacing = 17
      var count = 6
      var isCircle = false
      var guideText = '左右滑动 · 切换分类'
      if (shape === 'pill-shaped') {
        safeTopPx = 12
        base = 25
        designTop = 58
        iconW = 117
        spacing = 33
      } else if (shape === 'circle') {
        safeTopPx = 10
        base = 12
        designTop = 60
        iconW = 41
        spacing = 8
        count = 5
        isCircle = true
        guideText = '轻触图标 · 浏览分类'
      }
      var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
      self.topBarPadTop = padTop
      self.statusbarHeight = base + padTop
      self.catsMarginTop = Math.max(0, designTop - self.statusbarHeight)
      self.isCircle = isCircle
      self.guideText = guideText
      self.snapParams = { iconW: iconW, spacing: spacing, count: count, enabled: count > 5 }
      if (isCircle) {
        self.displayCats = self.categories.slice(0, 5)
      } else {
        self.displayCats = self.categories
      }
    }
  })
},

// 步长法计算吸附目标：gap 中点 = i*step + iconW + spacing/2（step = iconW + spacing），
// 目标 scrollX = gap - 视口中心(150)，钳制到 [0, contentW - 视口宽]
snapCatScroll() {
  var p = this.snapParams
  if (!p || !p.enabled) return
  var scrollEl = this.$element('catScroll')
  if (!scrollEl) return
  var curX = this.lastCatScrollX || 0
  var step = p.iconW + p.spacing
  var viewportW = 300
  var maxX = Math.max(0, p.count * p.iconW + p.count * p.spacing - viewportW)
  var viewCenter = viewportW / 2
  var bestX = 0
  var bestDist = Infinity
  for (var i = 0; i < p.count - 1; i++) {
    var gap = i * step + p.iconW + p.spacing / 2
    var target = gap - viewCenter
    if (target < 0) target = 0
    if (target > maxX) target = maxX
    var dist = Math.abs(target - curX)
    if (dist < bestDist) {
      bestDist = dist
      bestX = target
    }
  }
  // 已在吸附位附近则不重复滚动，避免循环
  if (Math.abs(bestX - curX) > 1) {
    scrollEl.scrollTo({ left: bestX, top: 0, behavior: 'smooth' })
  }
},

